# -*- coding: utf-8 -*-
from bookkit import *

def _rows(headers, labels):
    return form_table(headers, 0).replace("<tbody></tbody>", "<tbody>" + "".join(f"<tr><td>{x}</td>" + "<td></td>" * (len(headers) - 1) + "</tr>" for x in labels) + "</tbody>")

